-- Catalog content update 2026-11-17. MySQL 8. Not a Flyway schema migration.
-- Updates only when ALL 42 expected products/copy/units/prices still match.
-- Hex literals preserve Vietnamese independently of terminal encoding.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE greenfarm_catalog_copy (
    id BIGINT PRIMARY KEY, slug VARCHAR(255), old_name VARCHAR(255),
    old_description LONGTEXT, old_description_en LONGTEXT,
    old_unit VARCHAR(255), old_unit_en VARCHAR(255), old_price DECIMAL(10,2),
    new_description LONGTEXT, new_description_en LONGTEXT,
    new_unit VARCHAR(255), new_unit_en VARCHAR(255)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
START TRANSACTION;
SELECT p.id FROM products p JOIN greenfarm_catalog_copy c ON c.id=p.id ORDER BY p.id FOR UPDATE;
SET @catalog_matches=(SELECT COUNT(*) FROM products p JOIN greenfarm_catalog_copy c ON c.id=p.id WHERE BINARY p.slug = BINARY c.slug AND BINARY p.name = BINARY c.old_name
    AND (BINARY p.description <=> BINARY c.old_description)
    AND (BINARY p.description_en <=> BINARY c.old_description_en)
    AND (BINARY p.unit <=> BINARY c.old_unit)
    AND (BINARY p.unit_en <=> BINARY c.old_unit_en) AND p.price=c.old_price);
UPDATE products p JOIN greenfarm_catalog_copy c ON c.id=p.id
SET p.description=c.new_description, p.description_en=c.new_description_en,
    p.unit=c.new_unit, p.unit_en=c.new_unit_en, p.updated_at=UTC_TIMESTAMP()
WHERE @catalog_matches=42;
SET @catalog_changed=ROW_COUNT();
UPDATE inventory_batches b JOIN greenfarm_catalog_copy c ON c.id=b.product_id
SET b.unit=c.new_unit WHERE @catalog_matches=42 AND BINARY c.old_unit<>BINARY c.new_unit
AND BINARY b.unit=BINARY c.old_unit;
SET @batch_units_changed=ROW_COUNT();
COMMIT;
SELECT JSON_OBJECT('matchedExpectedProducts',@catalog_matches,'updatedProducts',@catalog_changed,'normalizedBatchUnits',@batch_units_changed,'verifiedProducts',(SELECT COUNT(*) FROM products p JOIN greenfarm_catalog_copy c ON c.id=p.id WHERE BINARY p.description = BINARY c.new_description
    AND BINARY p.description_en = BINARY c.new_description_en
    AND BINARY p.unit = BINARY c.new_unit AND BINARY p.unit_en = BINARY c.new_unit_en
    AND p.price=c.old_price));
DROP TEMPORARY TABLE greenfarm_catalog_copy;
